    s+=`<svg viewBox="-1.62 -1.45 3.24 2.92" role="img" aria-label="Top view of the head, nose at top, with the electrode positions" style="width:100%;max-width:560px;display:block;margin:auto"><defs><radialGradient id="vg"><stop offset="0" stop-color="var(--accent)" stop-opacity=".38"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></radialGradient><clipPath id="hc"><circle r="1.14"/></clipPath><marker id="ar" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6z" fill="var(--mark)"/></marker></defs>`;
