function polLab(H){const CH=['Fp1','F3','C3','P3','O1'],st={s:2,pol:-1,sg:.75};
  const card=el('div','card stack',`<div class="row" style="justify-content:space-between"><h2>Polarity lab: moving a source under a chain of leads</h2><div class="row" id="pCtl"></div></div><p style="max-width:84ch">A small patch of cortex, a <i>source</i>, makes a field that falls off with distance. Slide it along the left parasagittal chain (Fp1, F3, C3, P3, O1). The top row is the field on the scalp. The middle row is what a bipolar chain draws, each channel Input 1 minus Input 2. The bottom row is what each electrode draws against a quiet reference.</p><div id="pSl" class="stack" style="gap:8px"></div><canvas style="display:block;width:100%;height:450px"></canvas><div id="pTx" class="note"></div>`);H.appendChild(card);
  const cv=$('canvas',card),sl=slider($('#pSl',card),'Source position',{min:-.5,max:4.5,step:.05,val:2,fmt:v=>`${v<-.2||v>4.2?'beyond the chain, near ':'near '}${CH[clamp(Math.round(v),0,4)]}`},v=>{st.s=v;draw()});
  segment($('#pCtl',card),[['-1','Surface-negative source'],['1','Surface-positive source']],'-1',v=>{st.pol=+v;draw()});segment($('#pCtl',card),[['.75','Superficial'],['1.5','Deeper, broader']],'.75',v=>{st.sg=+v;draw()});
  function draw(){const S=cvSetup(cv);if(!S)return;const{g,w,C}=S,ml=14,mr=14,X=i=>ml+(i+.7)/5.4*(w-ml-mr),V=i=>st.pol*Math.exp(-Math.pow(i-st.s,2)/(2*st.sg*st.sg)),fm=getComputedStyle(document.body).getPropertyValue('--font-mono'),ff_=getComputedStyle(document.body).fontFamily;
    const yA=78,kA=52,yB=212,kB=95,yC=386,kC=52;
    const lab=(t,y)=>{g.fillStyle=C.muted;g.font='10.5px '+fm;g.textAlign='left';g.fillText(t,ml,y)};
    const arrow=(x,y0,dy,col)=>{g.strokeStyle=col;g.fillStyle=col;g.lineWidth=3;if(Math.abs(dy)<2.5){g.beginPath();g.arc(x,y0,2.6,0,6.3);g.fill();return}g.beginPath();g.moveTo(x,y0);g.lineTo(x,y0+dy-Math.sign(dy)*7);g.stroke();g.beginPath();g.moveTo(x,y0+dy);g.lineTo(x-6,y0+dy-Math.sign(dy)*10);g.lineTo(x+6,y0+dy-Math.sign(dy)*10);g.closePath();g.fill()};
    [yA,yB,yC].forEach(y=>{g.strokeStyle=C.major;g.lineWidth=1;g.beginPath();g.moveTo(ml,y+.5);g.lineTo(w-mr,y+.5);g.stroke()});
    lab('SCALP POTENTIAL  (negativity plotted up)',14);lab('BIPOLAR CHAIN  (Input 1 − Input 2)',140);lab('REFERENTIAL  (each electrode − quiet reference)',318);
    g.strokeStyle=C.ink;g.lineWidth=1.6;g.beginPath();for(let px=0;px<=w-ml-mr;px+=2){const i=(px/(w-ml-mr)*5.4)-.7;const x=ml+px,y=yA+V(i)*kA;px?g.lineTo(x,y):g.moveTo(x,y)}g.stroke();
    const ds=[];for(let j=0;j<4;j++)ds.push(V(j)-V(j+1));
    CH.forEach((n,i)=>{g.fillStyle=C.ink;g.beginPath();g.arc(X(i),yA+V(i)*kA,4,0,6.3);g.fill();g.fillStyle=C.muted;g.font='11px '+fm;g.textAlign='center';g.fillText(n,X(i),st.pol<0?yA+17:yA-10)});
    const col=d=>d>0?C.mark:C.accent;
    ds.forEach((d,j)=>{const x=(X(j)+X(j+1))/2;arrow(x,yB,d*kB,col(d));g.fillStyle=C.muted;g.font='11px '+fm;g.textAlign='center';g.fillText(CH[j]+'–'+CH[j+1],x,yB+72)});
    CH.forEach((n,i)=>{const v=V(i);arrow(X(i),yC,v*kC,col(v));g.fillStyle=C.muted;g.font='11px '+fm;g.textAlign='center';g.fillText(n,X(i),yC+52)});
    g.font='11px '+ff_;g.textAlign='right';g.fillStyle=C.accent;g.fillText('▲ up = Input 1 more negative',w-mr,14);g.fillStyle=C.mark;g.fillText('▼ down = Input 1 more positive',w-mr,28);
    // reversal
    const sig=[];ds.forEach((d,j)=>{if(Math.abs(d)>.05)sig.push(j)});let rev=null;for(let k=0;k<sig.length-1;k++){const a=sig[k],b=sig[k+1];if(ds[a]*ds[b]<0){rev={a,b};break}}
    const dir=d=>d>0?'down':'up';let tx;
    if(rev){const{a,b}=rev;const neg=ds[a]>0,at=b===a+1?CH[b]:null,x0=at?X(b):(X(a+1)+X(b))/2;g.strokeStyle=C.good;g.lineWidth=1.5;g.setLineDash([5,4]);g.beginPath();g.moveTo(x0,30);g.lineTo(x0,yC+36);g.stroke();g.setLineDash([]);g.fillStyle=C.good;g.font='600 11px '+fm;g.textAlign='center';g.fillText('phase reversal',x0,122);
      tx=at?`<b>Phase reversal at ${at}.</b> ${CH[a]}–${CH[a+1]} deflects <b>${dir(ds[a])}</b> and ${CH[b]}–${CH[b+1]} deflects <b>${dir(ds[b])}</b>. The tips point <b>${neg?'toward':'away from'}</b> each other, so the focus is <b>${neg?'surface-negative':'surface-positive'}</b> and lies under <b>${at}</b>.`:`<b>Reversal across a flat channel.</b> The source sits between ${CH[a+1]} and ${CH[b]}, which read nearly the same (equipotential), so their channel is flat and the reversal straddles it. The focus is ${neg?'surface-negative':'surface-positive'}.`}
    else tx=`<b>No phase reversal.</b> The source is beyond the end of this chain, so every channel deflects the same way and the amplitude is biggest at the end nearest the source. A chain that shows no reversal does not contain the focus. You need a neighbouring chain.`;
    tx+=` In the bottom row, the electrode with the tallest arrow is the one closest to the source.`;$('#pTx',card).innerHTML=tx}
  AX.polDraw=draw}

/* ---- Signal & filters panel ---- */
const stageFc=(k,f,n)=>{const q=Math.sqrt(Math.pow(2,1/n)-1);return k==='hp'?f*q:f/q};
function rc1(x,fc,type){const K=Math.tan(Math.PI*fc/FS),y=new Float32Array(x.length);let px=x[0],py=type==='lp'?x[0]:0;if(type==='lp'){const a=K/(1+K),b=(1-K)/(1+K);for(let i=0;i<x.length;i++){py=a*(x[i]+px)+b*py;px=x[i];y[i]=py}}else{const c=1/(1+K),b=(1-K)/(1+K);for(let i=0;i<x.length;i++){py=c*(x[i]-px)+b*py;px=x[i];y[i]=py}}return y}
function magK(k,f){const w=2*Math.PI*f/FS,c1=Math.cos(w),s1=Math.sin(w),c2=Math.cos(2*w),s2=Math.sin(2*w);return Math.hypot(k[0]+k[1]*c1+k[2]*c2,k[1]*s1+k[2]*s2)/Math.hypot(1+k[3]*c1+k[4]*c2,k[3]*s1+k[4]*s2)}
function gainRC(kind,f,fc,n){const x=Math.tan(Math.PI*f/FS)/Math.tan(Math.PI*fc/FS);return kind==='lp'?Math.pow(1/Math.sqrt(1+x*x),n):Math.pow(x/Math.sqrt(1+x*x),n)}
const NOTCH=bq('notch',60,25);
const card=(h,body)=>el('div','card stack',`<h2>${h}</h2>${body}`);

function buildSig(){const H=$('#aSig');H.innerHTML='';
  // 1. pipeline
  H.appendChild(el('div','card stack',`<h2>From brain to screen: how a scalp signal is measured</h2><p style="max-width:84ch">A scalp EEG is a few tens of microvolts, about a thousand times smaller than the ECG on the same patient. Everything that makes a tracing clear is about protecting that tiny difference from much larger interference. Follow the chain left to right.</p>
  <div class="pipe"><div class="stage"><b>1 Electrode and skin</b><span>Silver/silver chloride or gold cup with conductive gel on abraded skin. Aim for impedance under 5 kΩ and similar at every site.</span></div><div class="stage"><b>2 Differential amplifier</b><span>Subtracts Input 2 from Input 1 and multiplies the difference about 1000 times. Noise common to both inputs cancels. A ground electrode anchors the patient. Good amplifiers reject common signals by more than 100 dB.</span></div><div class="stage"><b>3 Anti-alias filter</b><span>A hardware low-pass keeps frequencies above half the sampling rate out, so they cannot fold back as false slow waves.</span></div><div class="stage"><b>4 Digitizer</b><span>Samples 256 to 512 times a second or more, with enough resolution to see a fraction of a microvolt.</span></div><div class="stage"><b>5 Display filters</b><span>Low-frequency filter (high-pass), high-frequency filter (low-pass) and a 60 Hz notch are chosen for each view and normally leave the stored data untouched.</span></div><div class="stage"><b>6 Display</b><span>Sensitivity in µV per mm (7 is typical) and a 30 mm per second time base.</span></div></div>
  <ul class="f" style="columns:2;column-gap:28px"><li>Brain: 10 to 100 µV, 0.5 to 40 Hz mostly</li><li>ECG: about 1 mV on the chest, much less on the scalp</li><li>Muscle: hundreds of µV, 20 to 300 Hz</li><li>Mains pickup: can be thousands of µV at the input, at exactly 60 Hz (50 Hz in many countries)</li><li>Sweat and electrode drift: hundreds of µV, below 0.5 Hz</li><li>Eye movement: hundreds of µV, below about 5 Hz</li></ul>`));

  // 2. reading amplitude and time
  const rd=el('div','card stack',`<h2>Measuring a wave on the page</h2><p style="max-width:84ch">The standard display is <b>30 mm per second</b>, so 1 mm is about 33 ms and 30 mm is exactly 1 s. Height is set by the <b>sensitivity</b>: at 7 µV/mm, a wave 5 mm tall (peak to peak) is 35 µV. Count waves, measure the paper, and the arithmetic follows.</p><div class="calc"><label>Waves counted<input type="number" id="cN" value="10" min="1" step="1"></label><label>over (mm of paper)<input type="number" id="cD" value="30" min="1" step="1"></label><label>Paper speed<select id="cS"><option>15</option><option selected>30</option><option>60</option></select></label><label>Wave height (mm, peak to peak)<input type="number" id="cH" value="5" min="0" step=".5"></label><label>Sensitivity (µV/mm)<select id="cV"><option>3</option><option>5</option><option selected>7</option><option>10</option><option>15</option><option>20</option></select></label></div><p id="cOut" class="note"></p>`);H.appendChild(rd);
  const calc=()=>{const n=+$('#cN',rd).value,d=+$('#cD',rd).value,sp=+$('#cS',rd).value,h=+$('#cH',rd).value,sv=+$('#cV',rd).value;const f=d>0?n/(d/sp):0;const b=f<.5?'infraslow':f<4?'delta':f<8?'theta':f<13?'alpha range':f<=30?'beta':'gamma';$('#cOut',rd).innerHTML=`<b>${f.toFixed(1)} Hz</b> (${b}). ${n} waves in ${(d/sp).toFixed(2)} s. Amplitude <b>${(h*sv).toFixed(0)} µV</b> peak to peak. One cycle is ${(1000/Math.max(f,.01)).toFixed(0)} ms.`};$$('input,select',rd).forEach(i=>i.addEventListener('input',calc));calc();

  diffLab(H);filtLab(H);rcLab(H);aliasLab(H);

  // checklist
  H.appendChild(el('div','card two',`<div><h3>Settings in routine use</h3><div class="tw"><table><thead><tr><th>Filter</th><th>Corner</th><th>Time constant</th></tr></thead><tbody>${[['Low-frequency (high-pass)',.1],['',.3],['',.5],['',1],['',5],['High-frequency (low-pass)',15],['',35],['',70]].map(([n,f],i)=>`<tr><td>${n||''}</td><td>${f} Hz</td><td>${(1/(2*Math.PI*f)).toFixed(f<2?2:3)} s</td></tr>`).join('')}</tbody></table></div><p class="lbl" style="margin-top:8px">Time constant TC = 1 ÷ (2π × corner frequency)</p></div>
  <div><h3>Pitfalls</h3><ul class="f"><li><b>Low-frequency filter too high</b> (above about 1 Hz) removes true delta, shrinks slow waves and bends the baseline after every big deflection.</li><li><b>High-frequency filter too low</b> rounds off spikes so they look like slow waves and hides fast activity. It also removes muscle, which can make a tracing look cleaner than the recording was.</li><li><b>The 60 Hz notch</b> hides, rather than cures, a poor electrode connection. Fix the contact first, and use the notch last.</li><li><b>Filters ring.</b> A sharp event passed through a filter can leave an echo that looks like a second wave, and a filtered tracing is not a faithful copy of what the brain did.</li><li><b>Compare before you conclude.</b> If a pattern changes drastically when a filter is changed, it was filter-sensitive. Review it with wide settings.</li></ul></div>`));
  H.appendChild(el('div','card stack',`<h2>Checklist for a clean tracing</h2><ul class="f" style="columns:2;column-gap:28px"><li><b>Skin and electrodes.</b> Abrade, gel, check impedance under 5 kΩ and balanced between sites.</li><li><b>Matched impedance.</b> Common-mode rejection is only as good as the match between the two inputs.</li><li><b>Ground and shielding.</b> Short twisted leads, keep cables away from mains cords and monitors, one ground.</li><li><b>Right montage.</b> Bipolar to localize, referential for field and amplitude, average reference only with wide coverage.</li><li><b>Filters in their place.</b> Wide while reading, narrow only to confirm, notch last.</li><li><b>Sampling high enough.</b> At least 3 times the highest frequency of interest, with the anti-alias filter on.</li><li><b>Document artifacts.</b> Tag blinks, chewing, movement and electrode pops so they are not read as brain.</li><li><b>Averaging.</b> For evoked responses, noise falls with the square root of the number of trials averaged, so 100 trials gain 10 times in signal-to-noise.</li></ul>`));
  AX.draws.sig=[()=>AX.sigDraw.forEach(f=>f())]}
AX.sigDraw=[];

/* ---- differential amplifier lab ---- */
function diffLab(H){const LEN=400,r=mkRand(41),t=i=>i/FS,st={mains:300,m:.25};
  const p=phs(r,10,.03,LEN),e=envl(r,.6,LEN),n1=bn(r,3,8,1,LEN),n2=bn(r,3,8,1,LEN),a=new Float32Array(LEN),b=new Float32Array(LEN),mains=new Float32Array(LEN);
  for(let i=0;i<LEN;i++){a[i]=Math.sin(p[i])*e[i]*26+n1[i]*6;mains[i]=Math.sin(6.2832*60*t(i))}for(let i=0;i<LEN;i++)b[i]=.6*(a[Math.max(0,i-8)])+n2[i]*7;
  const c=el('div','card stack',`<h2>Why two inputs? The differential amplifier</h2><p style="max-width:84ch">Both electrodes pick up the same 60 Hz hum from the room, hundreds of times bigger than the brain signal. Because the hum is <i>common</i> to both inputs, subtracting one from the other removes it, while the brain signal, which differs between sites, survives. The cancellation is only as good as the <b>balance</b> between the two skin contacts. Unequal impedance turns some of the common hum into a difference.</p><div id="dfS" class="stack" style="gap:8px"></div><div class="vwrap"><div id="dfC"></div></div><p id="dfT" class="note"></p>`);H.appendChild(c);
  const cv=mkCanvas($('#dfC',c),400),sm=slider($('#dfS',c),'Mains pickup',{min:0,max:600,step:10,val:300,fmt:v=>v+' µV'},v=>{st.mains=v;draw()}),si=slider($('#dfS',c),'Impedance mismatch',{min:0,max:100,step:1,val:25,fmt:v=>v+' %'},v=>{st.m=v/100;draw()});
  const bt=el('button','btn small','Prepare the skin (match the contacts)');bt.type='button';bt.addEventListener('click',()=>{si.set(3);st.m=.03;draw()});$('#dfS',c).appendChild(bt);
  function draw(){const e1=new Float32Array(LEN),e2=new Float32Array(LEN),out=new Float32Array(LEN),idl=new Float32Array(LEN);for(let i=0;i<LEN;i++){e1[i]=a[i]+st.mains*mains[i];e2[i]=b[i]+(1-st.m)*st.mains*mains[i];out[i]=e1[i]-e2[i];idl[i]=a[i]-b[i]}
    const rows=[{data:e1,label:'Electrode 1',sub:'EEG + hum',px:.1},{data:e2,label:'Electrode 2',sub:'EEG + hum (unequal)',px:.1},{data:out,label:'Output',sub:'Input 1 − Input 2',px:.8,color:cssv().accent},{data:idl,label:'Ideal',sub:'no hum at all',px:.8}];
    cv.style.height=(4+rows.length*88+22)+'px';drawRows(cv,rows,{rowH:88,t0:0,dur:2,labelW:132,lw:1.2});
    const res=st.m*st.mains,rej=st.m>0?20*Math.log10(1/st.m):Infinity;$('#dfT',c).innerHTML=`Hum left in the output: <b>${res.toFixed(0)} µV</b> (hum in each electrode ${st.mains} µV; ideal EEG difference about 25 µV). Rejection achieved: <b>${isFinite(rej)?rej.toFixed(0)+' dB':'complete'}</b>. ${st.m>.1?'The brain signal is buried: this is why high or unequal electrode impedance makes a 60 Hz tracing.':st.m>.03?'Better. The hum is smaller than the EEG but still visible.':'The hum cancels almost completely.'}`}
  AX.sigDraw.push(draw)}

/* ---- filter lab ---- */
function filtLab(H){const L=6000,r=mkRand(23),st={lff:.5,hff:70,notch:false,ord:1,on:new Set(['spk','drift','emg','mains'])},T0=20,DU=5;
  const x={eeg:new Float32Array(L),spk:new Float32Array(L),drift:bn(r,.05,.4,150,L),emg:bn(r,25,85,12,L),mains:new Float32Array(L),ecg:new Float32Array(L)};
  {const p=phs(r,10,.04,L),e=envl(r,.9,L),th=bn(r,4,7.5,7,L),de=bn(r,.5,3.5,14,L);for(let i=0;i<L;i++){x.eeg[i]=Math.sin(p[i])*e[i]*22+th[i]+de[i];x.mains[i]=30*Math.sin(6.2832*60*i/FS)}
   [21.6,23.9].forEach(c=>{for(let i=Math.floor((c-.1)*FS);i<(c+.7)*FS;i++){const q=i/FS-c;x.spk[i]+=-95*Math.exp(-Math.pow(q/.012,2))-45*Math.exp(-Math.pow((q-.15)/.09,2))}});
   for(let b=0;b*.8<L/FS;b++){const c=b*.8+.3;for(let i=Math.max(0,Math.floor((c-.2)*FS));i<Math.min(L,(c+.5)*FS);i++){const q=i/FS-c;x.ecg[i]+=60*Math.exp(-Math.pow(q/.011,2))+10*Math.exp(-Math.pow((q-.25)/.05,2))}}}
  const c=el('div','card stack',`<h2>Filters: what each one removes, and what it costs</h2><p style="max-width:84ch">Start with a recording contaminated by drift, muscle and mains hum, and watch the filters clean it. The bottom trace is the result; the top trace is the brain activity we hoped to recover. The response curve shows how each frequency is treated, with the EEG bands shaded. Push the low-frequency filter up and the delta band and the slow wave of the spike disappear. Pull the high-frequency filter down and the spike is rounded off.</p><div class="row" id="fChips"></div><div id="fS" class="stack" style="gap:8px"></div><div class="row" id="fCtl"></div><div class="vwrap"><div id="fC"></div></div><div class="vwrap"><div id="fR"></div></div><p id="fT" class="note"></p>`);H.appendChild(c);
  const chips=[['spk','Spike and slow wave'],['drift','Sweat / drift'],['emg','Muscle (EMG)'],['mains','60 Hz hum'],['ecg','ECG']];chips.forEach(([k,t])=>{const b=el('button','chip',t);b.type='button';b.setAttribute('aria-pressed',String(st.on.has(k)));b.addEventListener('click',()=>{st.on.has(k)?st.on.delete(k):st.on.add(k);b.setAttribute('aria-pressed',String(st.on.has(k)));draw()});$('#fChips',c).appendChild(b)});
  slider($('#fS',c),'Low-frequency filter',{min:.05,max:10,log:1,val:.5,fmt:v=>v.toFixed(v<1?2:1)+' Hz'},v=>{st.lff=v;draw()});slider($('#fS',c),'High-frequency filter',{min:10,max:90,log:1,val:70,fmt:v=>v.toFixed(0)+' Hz'},v=>{st.hff=v;draw()});
  const nl=el('label','row lbl','60 Hz notch');nl.style.cssText='gap:6px;text-transform:none;letter-spacing:0';const nc=el('input');nc.type='checkbox';nc.addEventListener('change',()=>{st.notch=nc.checked;draw()});nl.prepend(nc);$('#fCtl',c).appendChild(nl);
  const ol=el('span','lbl','Steepness');$('#fCtl',c).appendChild(ol);segment($('#fCtl',c),[['1','Gentle (1 stage)'],['2','Steeper (2)'],['4','Steep (4)']],'1',v=>{st.ord=+v;draw()});
  const cv=mkCanvas($('#fC',c),300),rcv=mkCanvas($('#fR',c),230);
  const gainAt=f=>{let g=1;for(let k=0;k<st.ord;k++)g*=gainRC('hp',f,stageFc('hp',st.lff,st.ord),1)*gainRC('lp',f,stageFc('lp',st.hff,st.ord),1);if(st.notch)g*=magK(NOTCH,f);return g};
  function draw(){const clean=new Float32Array(L),raw=new Float32Array(L);for(let i=0;i<L;i++){clean[i]=x.eeg[i]+(st.on.has('spk')?x.spk[i]:0);let v=clean[i];['drift','emg','mains','ecg'].forEach(k=>{if(st.on.has(k))v+=x[k][i]});raw[i]=v}
    let y=raw;for(let k=0;k<st.ord;k++)y=rc1(y,stageFc('hp',st.lff,st.ord),'hp');for(let k=0;k<st.ord;k++)y=rc1(y,stageFc('lp',st.hff,st.ord),'lp');if(st.notch)y=runbq(y,NOTCH);
    const rows=[{data:clean,label:'Brain signal',sub:'what we want',color:cssv().good},{data:raw,label:'Recorded',sub:'signal + noise'},{data:y,label:'After filters',sub:'what you see',color:cssv().accent}];
    cv.style.height=(4+rows.length*96+22)+'px';drawRows(cv,rows,{rowH:96,t0:T0,dur:DU,norm:true,labelW:112,lw:1.2});
    // response
    const S=cvSetup(rcv);if(S){const{g,w,h,C}=S,fm=getComputedStyle(document.body).getPropertyValue('--font-mono'),ml=44,mr=12,mt=22,mb=28,pw=w-ml-mr,ph=h-mt-mb,fx=f=>ml+Math.log10(f/.1)/3*pw,dy=d=>mt+(-d/60)*ph;
      BD.filter(b=>b.id!=='slow'&&b.id!=='mu'&&b.id!=='sigma').forEach(b=>{const r_={delta:[.5,4],theta:[4,8],alpha:[8,13],beta:[13,30],gamma:[30,80]}[b.id];g.globalAlpha=.16;g.fillStyle=b.color;g.fillRect(fx(r_[0]),mt,fx(r_[1])-fx(r_[0]),ph);g.globalAlpha=1;g.fillStyle=b.color;g.font='600 10.5px '+fm;g.textAlign='center';g.fillText(b.name.toLowerCase(),(fx(r_[0])+fx(r_[1]))/2,mt-7)});
      g.strokeStyle=C.grid;g.lineWidth=1;g.fillStyle=C.muted;g.font='10.5px '+fm;for(let d=0;d>=-60;d-=20){g.beginPath();g.moveTo(ml,dy(d)+.5);g.lineTo(w-mr,dy(d)+.5);g.stroke();g.textAlign='right';g.fillText(d+' dB',ml-5,dy(d)+4)}
      [.1,1,10,100].forEach(f=>{g.strokeStyle=C.major;g.beginPath();g.moveTo(fx(f)+.5,mt);g.lineTo(fx(f)+.5,mt+ph);g.stroke();g.textAlign='center';g.fillText(f+' Hz',fx(f),h-9)});
      g.strokeStyle=C.bad;g.setLineDash([4,4]);g.beginPath();g.moveTo(fx(60),mt);g.lineTo(fx(60),mt+ph);g.stroke();g.setLineDash([]);g.fillStyle=C.bad;g.textAlign='right';g.fillText('mains',fx(60)-4,mt+ph-6);g.fillText('muscle →',fx(25)-2,mt+ph-6);g.textAlign='left';g.fillText('drift',fx(.1)+4,mt+ph-6);
      g.strokeStyle=C.accent;g.lineWidth=2.6;g.beginPath();for(let k=0;k<=360;k++){const f=.1*Math.pow(1000,k/360),gv=Math.max(gainAt(f),1e-3),d=clamp(20*Math.log10(gv),-60,0);k?g.lineTo(fx(f),dy(d)):g.moveTo(fx(f),dy(d))}g.stroke();
      [[st.lff],[st.hff]].forEach(([f])=>{g.fillStyle=C.accent;g.beginPath();g.arc(fx(f),dy(-3),4,0,6.3);g.fill()})}
    const gp=f=>(gainAt(f)*100).toFixed(f>=60?1:0)+'%',tc=1/(2*Math.PI*st.lff);
    $('#fT',c).innerHTML=`<b>−3 dB corners ${st.lff.toFixed(st.lff<1?2:1)} Hz and ${st.hff.toFixed(0)} Hz</b> (low-frequency filter time constant ${tc.toFixed(2)} s). Passes at 1 Hz (delta): <b>${gp(1)}</b> · 5 Hz (theta): <b>${gp(5)}</b> · 10 Hz (alpha): <b>${gp(10)}</b> · 20 Hz (beta): <b>${gp(20)}</b> · 60 Hz: <b>${gp(60)}</b>. ${st.lff>=2?'The low-frequency filter is now eating real delta.':st.hff<=25?'The high-frequency filter is now rounding spikes and removing fast activity.':'This is close to a routine setting.'}`}
  AX.sigDraw.push(draw)}

/* ---- RC lab ---- */
function schem(t){const zig='M0 0h10l5-9 10 18 10-18 10 18 10-18 5 9h10',gnd='<path d="M138 100h24M142 106h16M146 112h8"/>',vz=`<g transform="translate(150 30) rotate(90)"><path d="${zig}"/></g>`;
  return`<svg viewBox="0 0 250 128" width="100%" style="max-width:340px" role="img" aria-label="${t==='lp'?'Low-pass':'High-pass'} RC circuit" fill="none" stroke="var(--ink)" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"><circle cx="12" cy="30" r="3.5" fill="var(--panel)"/>`+(t==='lp'?`<path d="M16 30H40"/><g transform="translate(40 30)"><path d="${zig}"/></g><path d="M110 30H235M150 30V62M138 62h24M138 70h24M150 70V100"/>${gnd}<text x="62" y="12" fill="var(--ink)" stroke="none" font-size="13" font-family="var(--font-mono)">R</text><text x="166" y="72" fill="var(--ink)" stroke="none" font-size="13" font-family="var(--font-mono)">C</text>`:`<path d="M16 30H70M70 14v32M78 14v32M78 30H235M150 30"/>${vz}<path d="M150 100"/>${gnd}<text x="68" y="10" fill="var(--ink)" stroke="none" font-size="13" font-family="var(--font-mono)">C</text><text x="166" y="68" fill="var(--ink)" stroke="none" font-size="13" font-family="var(--font-mono)">R</text>`)+`<circle cx="150" cy="30" r="3" fill="var(--ink)"/><circle cx="235" cy="30" r="3.5" fill="var(--panel)"/><text x="2" y="50" fill="var(--muted)" stroke="none" font-size="12" font-family="var(--font-mono)">Vin</text><text x="205" y="50" fill="var(--accent)" stroke="none" font-size="12" font-family="var(--font-mono)">Vout</text></svg>`}
function rcLab(H){const st={type:'lp',inp:'step',R:15915,C:1e-6,ratio:5};
  const c=el('div','card stack',`<h2>Resistor and capacitor: the filter you can build with two parts</h2><p style="max-width:84ch">A resistor and a capacitor together make a first-order filter, the building block behind EEG filtering. The capacitor charges through the resistor on a time scale of <b>τ = R × C</b>. The corner frequency is <b>fc = 1 ÷ (2π R C)</b>. Which part is in series decides what passes.</p>
   <ul class="f"><li><b>Low-pass</b> (resistor in series, output across the capacitor): slow changes get through, fast ones are smoothed away. Well above fc it <b>integrates</b>: the output is the running total of the input, so a square wave becomes a triangle.</li><li><b>High-pass</b> (capacitor in series, output across the resistor): only <i>changes</i> get through and a steady level drains away with time constant τ. Well below fc it <b>differentiates</b>: a square wave becomes spikes at the edges.</li><li>Put the two in series and you have a <b>band-pass</b>, exactly what an EEG amplifier does between its low-frequency and high-frequency filter settings.</li></ul>
   <div class="rcg"><div id="rcS" class="stack" style="gap:8px"><div class="row" id="rcCtl"></div><div id="rcSv"></div><div id="rcSl" class="stack" style="gap:8px"></div></div><div style="min-width:0"><div class="vwrap"><div id="rcT"></div></div><div class="vwrap" style="margin-top:10px"><div id="rcB"></div></div></div></div><p id="rcTx" class="note"></p>`);H.appendChild(c);
  segment($('#rcCtl',c),[['lp','Low-pass'],['hp','High-pass']],'lp',v=>{st.type=v;if(st.inp!=='step'){st.ratio=v==='lp'?5:.2;rs.set(st.ratio)}draw()});segment($('#rcCtl',c),[['step','Step'],['sq','Square wave'],['sin','Sine']],'step',v=>{st.inp=v;draw()});
  slider($('#rcSl',c),'Resistance R',{min:100,max:1e7,log:1,val:st.R,fmt:v=>fmtSI(v,'Ω')},v=>{st.R=v;draw()});slider($('#rcSl',c),'Capacitance C',{min:1e-9,max:1e-3,log:1,val:st.C,fmt:v=>fmtSI(v,'F')},v=>{st.C=v;draw()});
  const rs=slider($('#rcSl',c),'Input freq ÷ fc',{min:.05,max:20,log:1,val:5,fmt:v=>'× '+(+v.toPrecision(2))},v=>{st.ratio=v;draw()});
  const tcv=mkCanvas($('#rcT',c),240),bcv=mkCanvas($('#rcB',c),170);
  function draw(){$('#rcSv',c).innerHTML=schem(st.type);const tau=st.R*st.C,fc=1/(2*Math.PI*tau),per=st.inp!=='step';rs.input.disabled=!per;rs.input.parentElement.style.opacity=per?1:.45;
    let T,pre=0,inp;if(!per){T=7*tau;inp=t=>t>=tau?1:0}else{const f=st.ratio*fc,P=1/f;T=4*P;pre=6*P;inp=st.inp==='sq'?(t=>(t%P)<P/2?1:-1):(t=>Math.sin(2*Math.PI*f*t))}
    const n=1600,dt=(T+pre)/n,al=Math.exp(-dt/tau);let y=0;const xi=[],yo=[];for(let i=0;i<n;i++){const t=i*dt,x=inp(t);y=al*y+(1-al)*x;if(t>=pre){xi.push(x);yo.push(st.type==='lp'?y:x-y)}}
    let S=cvSetup(tcv);if(S){const{g,w,h,C}=S,fm=getComputedStyle(document.body).getPropertyValue('--font-mono'),ml=12,mr=12,mt=16,mb=26,pw=w-ml-mr,ph=h-mt-mb,lo=per?-1.25:-.1,hi=per?1.25:1.15,Y=v=>mt+(hi-v)/(hi-lo)*ph,Xn=i=>ml+i/(xi.length-1)*pw;
      g.strokeStyle=C.grid;g.lineWidth=1;g.beginPath();g.moveTo(ml,Y(0)+.5);g.lineTo(w-mr,Y(0)+.5);g.stroke();
      if(!per){
        for(let k=1;k<=5;k++){const x=ml+((tau+k*tau)/T)*pw;g.strokeStyle=C.major;g.beginPath();g.moveTo(x+.5,mt);g.lineTo(x+.5,mt+ph);g.stroke();g.fillStyle=C.muted;g.font='10.5px '+fm;g.textAlign='center';g.fillText(k+'τ',x,h-9)}
        const lv=st.type==='lp'?.632:.368;g.setLineDash([4,4]);g.strokeStyle=C.mark;g.beginPath();g.moveTo(ml,Y(lv));g.lineTo(w-mr,Y(lv));g.stroke();g.setLineDash([]);g.fillStyle=C.mark;g.textAlign='right';g.fillText(st.type==='lp'?'63% after 1τ':'37% left after 1τ',w-mr-2,Y(lv)-4)}
      else{g.fillStyle=C.muted;g.font='10.5px '+fm;g.textAlign='left';g.fillText('4 cycles = '+fmtSI(T,'s'),ml,h-9)}
      g.lineJoin='round';g.strokeStyle=C.muted;g.lineWidth=1.6;g.beginPath();xi.forEach((v,i)=>i?g.lineTo(Xn(i),Y(v)):g.moveTo(Xn(i),Y(v)));g.stroke();g.strokeStyle=C.accent;g.lineWidth=2.6;g.beginPath();yo.forEach((v,i)=>i?g.lineTo(Xn(i),Y(v)):g.moveTo(Xn(i),Y(v)));g.stroke();
      g.font='600 11px '+fm;g.textAlign='left';g.fillStyle=C.muted;g.fillText('input',ml+2,mt+6);g.fillStyle=C.accent;g.fillText('output',ml+46,mt+6)}
    S=cvSetup(bcv);if(S){const{g,w,h,C}=S,fm=getComputedStyle(document.body).getPropertyValue('--font-mono'),ml=44,mr=12,mt=12,mb=26,pw=w-ml-mr,ph=h-mt-mb,fx=r=>ml+(Math.log10(r)+2)/4*pw,dy=d=>mt+(-d/40)*ph;
      g.strokeStyle=C.grid;g.fillStyle=C.muted;g.font='10.5px '+fm;g.lineWidth=1;for(let d=0;d>=-40;d-=10){g.beginPath();g.moveTo(ml,dy(d)+.5);g.lineTo(w-mr,dy(d)+.5);g.stroke();g.textAlign='right';g.fillText(d+' dB',ml-5,dy(d)+4)}
      [.01,.1,1,10,100].forEach(r=>{g.strokeStyle=C.major;g.beginPath();g.moveTo(fx(r)+.5,mt);g.lineTo(fx(r)+.5,mt+ph);g.stroke();g.textAlign='center';g.fillText(r===1?'fc':'×'+r,fx(r),h-9)});
      g.strokeStyle=C.accent;g.lineWidth=2.6;g.beginPath();for(let k=0;k<=300;k++){const r=Math.pow(10,-2+4*k/300),m=st.type==='lp'?1/Math.sqrt(1+r*r):r/Math.sqrt(1+r*r),d=Math.max(-40,20*Math.log10(m));k?g.lineTo(fx(r),dy(d)):g.moveTo(fx(r),dy(d))}g.stroke();
      g.fillStyle=C.accent;g.beginPath();g.arc(fx(1),dy(-3.01),4,0,6.3);g.fill();if(per){g.strokeStyle=C.mark;g.setLineDash([4,4]);g.beginPath();g.moveTo(fx(st.ratio),mt);g.lineTo(fx(st.ratio),mt+ph);g.stroke();g.setLineDash([]);g.fillStyle=C.mark;g.textAlign='center';g.fillText('input',fx(st.ratio),mt+10)}
      g.fillStyle=C.muted;g.textAlign='left';g.fillText('−6 dB per octave beyond fc',ml+6,st.type==='lp'?dy(-30):dy(-6)-14)}
    const reg=!per?(st.type==='lp'?'After a step the output climbs toward the input and reaches 63% at 1τ, 95% at 3τ and 99% at 5τ.':'After a step the output jumps and then drains away: 37% remains at 1τ, 5% at 3τ. This is why a high low-frequency-filter setting makes slow waves and baseline shifts sag.'):(st.type==='lp'?(st.ratio>=3?'Input frequency is well above fc: the capacitor never gets time to charge, so the circuit <b>integrates</b>. A square wave becomes a triangle and the amplitude shrinks as frequency rises.':st.ratio<=.33?'Input frequency is well below fc: the output follows the input and passes unchanged.':'Near fc the output is attenuated to about 70% and delayed.'):(st.ratio<=.33?'Input frequency is well below fc: the circuit <b>differentiates</b>. A square wave becomes spikes at each edge; only changes get through.':st.ratio>=3?'Input frequency is well above fc: the signal passes unchanged.':'Near fc the output is attenuated to about 70% and shifted forward in time.'));
    $('#rcTx',c).innerHTML=`<b>τ = R × C = ${fmtSI(tau,'s')}</b> · <b>fc = 1 ÷ (2π R C) = ${fmtSI(fc,'Hz')}</b> · 10–90% rise time ≈ 2.2 τ = ${fmtSI(2.2*tau,'s')}. ${reg}`}
  AX.sigDraw.push(draw)}

/* ---- sampling and aliasing ---- */
function aliasLab(H){const st={f:70,fs:128};
  const c=el('div','card stack',`<h2>Sampling: why the digitizer rate and the low-pass filter go together</h2><p style="max-width:84ch">A digital recorder takes snapshots. To capture a wave it needs more than two snapshots per cycle (the <b>Nyquist rule</b>: sampling rate at least twice the highest frequency). A faster wave is not lost: it <b>folds back</b> and shows up as a slower, false wave. That is <b>aliasing</b>, and it is why the amplifier has a low-pass filter before the digitizer.</p><div id="aS" class="stack" style="gap:8px"></div><div class="vwrap"><div id="aC"></div></div><p id="aT" class="note"></p>`);H.appendChild(c);
  slider($('#aS',c),'Signal frequency',{min:1,max:240,step:1,val:70,fmt:v=>v+' Hz'},v=>{st.f=v;draw()});slider($('#aS',c),'Sampling rate',{min:32,max:512,log:1,val:128,fmt:v=>Math.round(v)+' Hz'},v=>{st.fs=Math.round(v);draw()});
  const cv=mkCanvas($('#aC',c),200);
  function draw(){const S=cvSetup(cv);if(!S)return;const{g,w,h,C}=S,fm=getComputedStyle(document.body).getPropertyValue('--font-mono'),ml=12,mr=12,mt=14,mb=22,pw=w-ml-mr,ph=h-mt-mb,W=.125,X=t=>ml+t/W*pw,Y=v=>mt+ph/2-v*ph*.42;
    g.strokeStyle=C.grid;g.lineWidth=1;g.beginPath();g.moveTo(ml,Y(0)+.5);g.lineTo(w-mr,Y(0)+.5);g.stroke();g.fillStyle=C.muted;g.font='10.5px '+fm;g.textAlign='left';g.fillText('0',ml,h-8);g.textAlign='right';g.fillText('125 ms',w-mr,h-8);
    g.strokeStyle=C.major;g.lineWidth=1.4;g.beginPath();for(let k=0;k<=pw;k++){const t=k/pw*W,v=Math.sin(2*Math.PI*st.f*t);k?g.lineTo(ml+k,Y(v)):g.moveTo(ml,Y(v))}g.stroke();
    const n=Math.floor(W*st.fs),pts=[];for(let i=0;i<=n;i++){const t=i/st.fs;pts.push([X(t),Y(Math.sin(2*Math.PI*st.f*t))])}g.strokeStyle=C.accent;g.lineWidth=2.4;g.lineJoin='round';g.beginPath();pts.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.stroke();g.fillStyle=C.accent;pts.forEach(p=>{g.beginPath();g.arc(p[0],p[1],3.2,0,6.3);g.fill()});
    g.font='600 11px '+fm;g.textAlign='left';g.fillStyle=C.muted;g.fillText('true wave',ml+2,mt+4);g.fillStyle=C.accent;g.fillText('what the recorder keeps',ml+74,mt+4);
    const nyq=st.fs/2,al=Math.abs(st.f-st.fs*Math.round(st.f/st.fs));$('#aT',c).innerHTML=st.f<nyq?`<b>${st.f} Hz is below the Nyquist limit of ${nyq} Hz</b> (${(st.fs/st.f).toFixed(1)} samples per cycle). The recorder keeps the wave faithfully, though with few samples per cycle the straight-line joins look angular.`:st.f===nyq?`<b>Exactly at the Nyquist limit.</b> Two samples per cycle is the bare minimum, and amplitude depends on where the samples happen to land.`:`<b>${st.f} Hz is above the Nyquist limit of ${nyq} Hz.</b> It is recorded as a false <b>${al.toFixed(0)} Hz</b> wave. A 60 Hz hum sampled at 100 Hz would appear as a 40 Hz wave, and fast muscle activity can masquerade as brain rhythm. The anti-alias filter must remove it <i>before</i> sampling, since afterwards it cannot be told apart from the real thing.`}
  AX.sigDraw.push(draw)}

